"""Server-side static PointCloud2 -> cached, merged geometric blocks.

These blocks describe occupied geometry, not semantic object detections. Original
ROS point clouds are never changed and are never sent to a web client.
"""
from __future__ import annotations

import gzip
import hashlib
import json
import os
import threading
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

import numpy as np

PROCESSOR_VERSION = "occupied-blocks-v3-detail025"
DETAIL_VOXEL_SIZE = 0.25
MAX_BOXES = 100000


def decode_xyz(message: Any) -> np.ndarray:
    """Respect PointCloud2 field offsets, endian flag and organized row padding."""
    width, height = int(message.width), int(message.height)
    if width * height > 6_000_000 or len(message.data) > 256_000_000:
        raise ValueError("静态点云超过服务端处理上限")
    if not width or not height or message.point_step <= 0:
        raise ValueError("静态点云为空")
    required = (height - 1) * message.row_step + width * message.point_step
    if message.row_step < width * message.point_step or len(message.data) < required:
        raise ValueError("点云行长度或数据长度无效")
    fields = {field.name: field for field in message.fields}
    columns = []
    for name in ("x", "y", "z"):
        field = fields.get(name)
        if field is None or field.datatype not in (7, 8) or field.count != 1:
            raise ValueError("点云需要 FLOAT32/FLOAT64 的 XYZ 字段")
        size = 4 if field.datatype == 7 else 8
        if field.offset < 0 or field.offset + size > message.point_step:
            raise ValueError("点云 XYZ 字段偏移无效")
        dtype = np.dtype((">" if message.is_bigendian else "<") + ("f4" if size == 4 else "f8"))
        values = np.ndarray((height, width), dtype=dtype, buffer=message.data,
                            offset=field.offset, strides=(message.row_step, message.point_step))
        columns.append(values.reshape(-1))
    points = np.column_stack(columns).astype(np.float32)
    points = points[np.isfinite(points).all(axis=1) & (np.abs(points) < 1e7).all(axis=1)]
    if not len(points):
        raise ValueError("点云没有有效坐标")
    return points


def merged_blocks(cells: np.ndarray, size: float) -> np.ndarray:
    """Merge occupied voxels into vertical runs, then identical adjacent strips.

    Never fill a cluster's entire bounding box: cavities and silhouettes remain.
    Output per block: centre XYZ, extent XYZ, six little-endian float32 values.
    """
    columns: Dict[Tuple[int, int], List[int]] = {}
    for x, y, z in cells.tolist():
        columns.setdefault((x, y), []).append(z)
    strips: Dict[Tuple[int, int, int], List[int]] = {}
    for (x, y), zs in columns.items():
        zs.sort()
        start = previous = zs[0]
        for z in zs[1:] + [zs[-1] + 2]:
            if z != previous + 1:
                strips.setdefault((y, start, previous + 1), []).append(x)
                start = z
            previous = z
    rectangles: Dict[Tuple[int, int, int, int], List[int]] = {}
    for (y, z0, z1), xs in strips.items():
        xs.sort()
        start = previous = xs[0]
        for x in xs[1:] + [xs[-1] + 2]:
            if x != previous + 1:
                rectangles.setdefault((start, previous + 1, z0, z1), []).append(y)
                start = x
            previous = x
    result = []
    for (x0, x1, z0, z1), ys in rectangles.items():
        ys.sort()
        start = previous = ys[0]
        for y in ys[1:] + [ys[-1] + 2]:
            if y != previous + 1:
                result.append(((x0 + x1) * size / 2, (start + previous + 1) * size / 2,
                               (z0 + z1) * size / 2, (x1 - x0) * size,
                               (previous + 1 - start) * size, (z1 - z0) * size))
                start = y
            previous = y
    return np.asarray(result, dtype="<f4").reshape(-1, 6)


def supported_cells(cells: np.ndarray, counts: np.ndarray) -> np.ndarray:
    """Keep thin, single-return cells if an axial neighbour supports them."""
    dimensions = (cells.max(axis=0).astype(np.int64) - cells.min(axis=0) + 3)
    if int(dimensions[0]) * int(dimensions[1]) * int(dimensions[2]) >= 2**62:
        raise ValueError("点云坐标跨度超过精细环境处理上限")
    shifted = cells.astype(np.int64) - cells.min(axis=0) + 1
    # np.unique supplies lexicographically sorted cells; padding prevents row
    # wraparound from becoming a false neighbour in the packed indices.
    keys = (shifted[:, 0] * dimensions[1] + shifted[:, 1]) * dimensions[2] + shifted[:, 2]
    keep = counts >= 2
    for stride in (1, int(dimensions[2]), int(dimensions[1] * dimensions[2])):
        for delta in (stride, -stride):
            neighbours = keys + delta
            indices = np.searchsorted(keys, neighbours)
            keep |= (indices < len(keys)) & (keys[np.minimum(indices, len(keys) - 1)] == neighbours)
    return cells[keep]


def simplify(points: np.ndarray, voxel_size: float) -> Tuple[np.ndarray, float, float]:
    # Dominant low surface estimates the ground; roads remain the authoritative
    # Lanelet layer. No inference of building/tree/vehicle classes is performed.
    lower = points[:, 2][points[:, 2] <= np.percentile(points[:, 2], 45)]
    bins, edges = np.histogram(lower, bins=max(1, min(500, int(np.ptp(lower) / .2) + 1)))
    peak = int(np.argmax(bins))
    ground = float(np.median(lower[(lower >= edges[peak]) & (lower <= edges[peak + 1])]))
    above = points[points[:, 2] > ground + .45]
    if not len(above):
        return np.empty((0, 6), dtype="<f4"), voxel_size, ground
    cells, counts = np.unique(np.floor(above / voxel_size).astype(np.int32), axis=0, return_counts=True)
    blocks = merged_blocks(supported_cells(cells, counts), voxel_size)
    if len(blocks) > MAX_BOXES:
        raise ValueError("精细环境超过 100000 块上限，需在后端按区域处理；未自动降低精度")
    return blocks, voxel_size, ground


class EnvironmentStore:
    def __init__(self, cache_dir: Optional[Path] = None) -> None:
        self.cache = cache_dir or Path(os.environ.get("NAV_WEB_ENV_CACHE", str(Path.home() / ".cache/nav_web/environment")))
        self.lock = threading.Lock()
        self.pool = ThreadPoolExecutor(max_workers=1, thread_name_prefix="static-map-preprocess")
        self.pending: Any = None
        self.running = False
        self.closed = False
        self.state = "waiting"
        self.error = "等待静态点云地图"
        self.result: Optional[Dict[str, Any]] = None

    def submit(self, message: Any) -> None:
        with self.lock:
            if self.closed:
                return
            self.pending = message  # bounded to the newest cloud while processing
            self.state, self.result, self.error = "processing", None, "环境地图正在预处理"
            if not self.running:
                self.running = True
                self.pool.submit(self._drain)

    def _drain(self) -> None:
        while True:
            with self.lock:
                message, self.pending = self.pending, None
                if message is None or self.closed:
                    self.running = False
                    return
            try:
                result = self._process(message)
                with self.lock:
                    if self.pending is None:
                        self.result, self.state, self.error = result, "ready", ""
            except Exception as error:
                with self.lock:
                    if self.pending is None:
                        self.state, self.error = "error", f"环境地图处理失败：{error}"

    def _process(self, message: Any) -> Dict[str, Any]:
        if not message.header.frame_id:
            raise ValueError("静态点云缺少坐标系")
        spec = json.dumps({"version": PROCESSOR_VERSION, "frame": message.header.frame_id,
                           "voxel_size": DETAIL_VOXEL_SIZE, "max_boxes": MAX_BOXES,
                           "width": message.width, "height": message.height,
                           "point_step": message.point_step, "row_step": message.row_step,
                           "bigendian": message.is_bigendian,
                           "fields": [(f.name, f.offset, f.datatype, f.count) for f in message.fields]}, sort_keys=True)
        digest = hashlib.sha256(spec.encode())
        digest.update(memoryview(message.data))
        asset_id = digest.hexdigest()
        self.cache.mkdir(parents=True, exist_ok=True)
        manifest_path = self.cache / f"{asset_id}.json"
        if manifest_path.exists():
            try:
                cached = json.loads(manifest_path.read_text())
                if (cached["asset_id"] == asset_id and cached["processor"] == PROCESSOR_VERSION and
                    set(cached["lods"]) == {"detail"} and
                    (self.cache / f"{asset_id}-detail.bin.gz").stat().st_size == cached["lods"]["detail"]["gzip_bytes"]):
                    return cached
            except (OSError, ValueError, KeyError, TypeError):
                pass  # rebuild an interrupted/corrupt manifest from the ROS source
        points = decode_xyz(message)
        manifest: Dict[str, Any] = {
            "asset_id": asset_id, "processor": PROCESSOR_VERSION, "format": "boxes-f32le-v1",
            "frame_id": message.header.frame_id, "source_points": int(message.width * message.height),
            "source_bytes": len(message.data), "bounds": [*points.min(axis=0).tolist(), *points.max(axis=0).tolist()],
            "lods": {},
        }
        for lod, size in (("detail", DETAIL_VOXEL_SIZE),):
            boxes, actual_size, ground = simplify(points, size)
            raw = boxes.tobytes()
            compressed = gzip.compress(raw, compresslevel=6, mtime=0)
            path = self.cache / f"{asset_id}-{lod}.bin.gz"
            temporary = path.with_suffix(".tmp")
            temporary.write_bytes(compressed)
            temporary.replace(path)
            manifest["lods"][lod] = {"box_count": len(boxes), "voxel_size": actual_size,
                                     "ground_z": ground, "bytes": len(raw), "gzip_bytes": len(compressed)}
        temporary = manifest_path.with_suffix(".tmp")
        temporary.write_text(json.dumps(manifest))
        temporary.replace(manifest_path)
        return manifest

    def snapshot(self) -> Dict[str, Any]:
        with self.lock:
            return {"status": self.state, "message": self.error, "asset": self.result}

    def close(self) -> None:
        with self.lock:
            self.closed, self.pending = True, None
        self.pool.shutdown(wait=True)
